/* ==========================================================================
 *  mnu/mnuitem.cpp
 *
 *  The item menu (0x1ae954..0x1bdae4; no source string names the file).
 *  See mnu/mnuitem.h.
 *
 *  PORT: the pattern tables are the ROM's .data words as they are (EE
 *  images, as in mnu/mnuopt.cpp): the display lists and the anim tables
 *  point into them by EE address, SprMan::eePtr resolves them against
 *  MNUITEMPATTERN_EE / MNUITEMFINDPATTERN_EE. Writable: SprMan writes the
 *  anim counts back, and setDisp writes the chapter's pattern into the
 *  display list.
 * ======================================================================== */
