int MnuItem::getZero()
{
    return 0;
}

// ──────────────────────────────────────────────────────────────────────
// The page m_page's handler; pages 0, 5, 7, 9, 10, 11 and 13 close the
// menu (step 6) when they return 1.
// ROR 0x001b1ba0

void MnuItem::execPage(BedPad *pad)
{
    int ret;

    switch (m_page) {
    case 0: ret = execPage0(pad); break;
    case 1: execPage1(pad); return;
    case 2: execPage2(pad); return;
    case 3: execPage3(pad); return;
    case 4: execPage4(pad); return;
    case 5: ret = execPage5(pad); break;
    case 6: execPage6(pad); return;
    case 7: ret = execPage7(pad); break;
    case 8: execPage8(pad); return;
    case 9: ret = execPage9(pad); break;
    case 10: ret = execPage10(pad); break;
    case 0xb: ret = execPage11(pad); break;
    case 0xc: execPage12(pad); return;
    case 0xd: ret = execPage13(pad); break;
    default: return;
    }
    if (ret == 1)
        m_step = 6;
}

